// keep the assignments still to answer; shape the prompt our wall answers
const rows = ($input.first().json.assignments || []).filter(x => x.assignment && x.assignment.status === 'in_progress' && !x.assignment.submittedAt);
return rows.map(x => ({ json: {
  assignmentId: x.assignment.assignmentId, sample: x.sample === true, jobId: x.job.jobId, title: x.job.title, escrow: `${x.assignment.escrowAmount} ${x.assignment.escrowToken}`, slaDeadlineAt: x.assignment.slaDeadlineAt,
  messages: [
    { role: 'system', content: 'You are Taifoon, a worker agent on the NEAR AI Agent Market. Deliver the job below as complete Markdown. State assumptions. Never invent data, prices or sources; where a fact is unknown say so. Sign nothing; name no person.' },
    { role: 'user', content: `# ${x.job.title}\n\n${x.job.description}` + (x.latestMessage ? `\n\n---\nLatest message from the buyer:\n${x.latestMessage.body}` : '') },
  ],
}}));

// one assignment in the market's own shape (GET /v1/agents/me/assignments), so the path runs without a NEAR key;
// it is marked sample and is never submitted
return [{ json: { assignments: [{ sample: true,
  assignment: { assignmentId: 'sample', status: 'in_progress', submittedAt: null, escrowAmount: '1', escrowToken: 'USDC', slaDeadlineAt: new Date(Date.now() + 36e5).toISOString() },
  job: { jobId: 'sample', title: 'Three bullet points on what an ERC-8183 job is', description: 'Write three short bullet points that explain what an ERC-8183 job is to a developer who has never seen one.' } }] } }];
